  "Providers": "模型供应商",
  "Create model pool": "创建模型池",
  "Combine multiple Provider model routes into one callable model alias with conditional routing rules, priority/weight failover, unified custom-model pricing or per-candidate pass-through billing, and strategy auditing.": "将多个 Provider 模型路由组合为一个可直接调用的模型别名，支持条件分流规则、优先级与权重容灾、自定义模型统一定价或按命中模型分别计费，以及路由策略审计。",
  "How routing & billing work": "路由与计费说明",
  "Routing rules, billing modes & audit": "条件路由、计费模式与策略审计",
  "Callers invoke the pool alias directly as the model field in /v1/chat/completions, /v1/responses, /v1/messages, or /v1/embeddings.": "调用方可在 /v1/chat/completions、/v1/responses、/v1/messages 或 /v1/embeddings 中直接将该模型池别名作为 model 参数调用。",
  "Ordered routing rules match request attributes (vision, tools, structured output, reasoning, token bounds) first; unmatched traffic uses the default pool candidates. Highest priority wins and weights split traffic.": "系统按顺序匹配条件分流规则（视觉输入、工具调用、结构化输出、推理、Token 区间），未命中的请求回退到默认候选模型。最高优先级层级胜出并按权重分配流量。",
  "Choose Unified pool price (pool_tariff) to sell the pool as a custom model at one retail tariff, or Per-candidate price (candidate_tariff) to bill customers at whichever candidate model handled the request.": "可选择“按模型池统一定价 (pool_tariff)”将其作为自定义模型售卖，或选择“按命中候选模型分别计费 (candidate_tariff)”按实际命中的底层模型扣费。",
