  "Latest 100 recorded blocks before model dispatch. Select a saved policy to inspect the rules referenced by a block. A workspace administrator can change policy for future requests. These pre-dispatch events may have no request log. Some admission denials are not recorded. Logs contain output blocks after dispatch.": "显示最近 100 条模型调度前的拦截记录。选择已保存策略以查看引用规则。工作空间管理员可修改后续请求的策略。调度前事件可能没有请求日志；部分受理拒绝不会记录。日志中包含调度后的输出拦截记录。",
