  "Pinned to {0} · Version {1}": "已固定到 {0} · 版本 {1}",
  "Workspace rules always apply. This key can follow the current workspace policy or pin a saved version that adds fixed restrictions.": "工作空间规则始终适用。此密钥可以跟随当前工作空间策略，或固定一个增加固定限制的已保存版本。",
  "Follow the workspace policy so later edits apply automatically, or pin a saved version for fixed additional restrictions. Workspace rules always apply.": "跟随工作空间策略，后续编辑会自动生效；或固定已保存版本以增加固定限制。工作空间规则始终适用。",
  "This key uses the workspace's active policy. Later workspace edits apply without re-pinning the key.": "此密钥使用工作空间的当前策略。后续工作空间编辑会自动生效，无需重新固定密钥。",
  "No workspace policy is active yet. The key will use the first active policy when one is saved.": "尚未启用工作空间策略。保存第一个策略后，此密钥将使用该策略。",
  "Pinned versions add fixed restrictions. Later workspace edits do not update this pin.": "固定版本会增加固定限制。后续工作空间编辑不会更新此固定分配。",
  "This key now follows the workspace policy.": "此密钥现跟随工作空间策略。",
  "Saved policy version pinned to this key.": "已将保存的策略版本固定到此密钥。",
  "· Version": "· 版本",
  "Loading saved versions…": "正在加载已保存版本…",
