  "Counts dispatched requests in a rolling 60-second window, including failed requests.": "统计滚动 60 秒窗口内的调度请求，包括失败的请求。",
  "Counts unresolved dispatched requests. Disconnecting does not release an unresolved request.": "统计尚未完成的调度请求。断开连接不会释放未完成的请求。",
  "Counts known usage and unresolved estimates. A finite limit requires supported text requests with an explicit output-token maximum; video requests are blocked.": "统计已知用量和未核定估算。有限限额要求受支持的文本请求明确指定输出 Token 上限；视频请求会被阻止。",
  "Leave blank for unlimited. Zero blocks new requests.": "留空表示不限额。零会阻止新请求。",
