  "The recorded amount is the exact sum of the selected earnings. After submission, the reference and selection are locked so retries record the same payment.": "记录金额为所选收益的精确总和。提交后编号与选择锁定，重试将记录同一付款。",
  "This records an external payment that has already completed. It does not initiate a transfer. Niu includes every unpaid earning in the selected currency through the cutoff.": "此操作记录已完成的外部付款，不会发起转账。Niu 将包含所选币种截至截止日期的全部未付收益。",
  "No unpaid earnings are available to settle.": "暂无可结算的未付收益。",
  "Earnings through": "收益截止日期",
  "Includes unpaid earnings created on or before this date, through the end of the day in your local time. Later earnings remain unpaid.": "包含截至该日期（按本地时间当日结束）创建的未付收益。之后的收益仍保持未付。",
