  "The recorded amount is the exact sum of the unpaid earnings included. After submission, the reference, currency and cutoff are locked so retries record the same payment.": "记录金额为所含未付收益的精确总和。提交后编号、币种与截止日期锁定，重试将记录同一付款。",
  "This area is for approved providers earning revenue on Niu. Your account needs an active provider membership.": "此区域供在 Niu 赚取收益的已批准 Provider 使用，账户需具备有效 Provider 成员资格。",
