  "Manage materials and identity verification required by your video Provider. Create videos and revisit previous results in": "管理视频 Provider 所需材料与身份验证。创建视频及回看结果请前往",
  ". Available tools depend on the selected model.": "。可用工具取决于所选模型。",
  "The verification was saved but its outcome is not confirmed. Check its status before starting another attempt.": "核验已保存，但结果尚未确认。开始新尝试前请检查其状态。",
  "The selected item is no longer available. Refresh and try again.": "所选项目已不可用，请刷新后重试。",
  "Showing the last loaded material details; latest status could not be refreshed.": "显示的是上次加载的材料详情；最新状态无法刷新。",
  "The Provider did not receive this change. You can try again.": "Provider 未收到此更改，可以重试。",
  "{0} The outcome is unconfirmed. Check its status before trying again.": "{0} 结果尚未确认。重试前请检查其状态。",
  "{0} Retry the same request safely; editing is disabled to avoid creating a duplicate.": "{0} 请安全重试同一请求；为避免重复创建，编辑已禁用。",
  "{0} The outcome remains unconfirmed. Try checking again.": "{0} 结果仍未确认，请再次检查。",
  "A saved change is waiting to be sent. Check its status before starting another attempt.": "有一项已保存的更改等待发送。开始新尝试前请检查其状态。",
  "A previous change is unconfirmed. Check its status before making the same change again.": "上次更改尚未确认。再次进行相同更改前请检查其状态。",
  "Your current network is not in this key’s source IP allowlist, so live Provider materials and verification cannot be queried with this key. Choose another API key, or add your current IP address to this key’s source IP policy.": "当前网络不在该密钥的来源 IP 白名单内，无法使用该密钥访问实时上游素材与核验功能。请切换其他 API 密钥，或将当前网络 IP 添加至该密钥的来源 IP 策略中。",
  "Delete material “{0}” from {1}? This removes the material from the Provider and cannot be undone.": "从 {1} 删除材料“{0}”？这会从 Provider 删除材料，且无法撤销。",
  "Delete material group “{0}”? This removes the group from the Provider and cannot be undone.": "删除材料分组“{0}”？这会从 Provider 删除分组，且无法撤销。",
  "The Provider downloads this file from a public HTTPS URL. Workspace media is private and cannot be reached by the Provider; use a public HTTPS link to the same file instead.": "Provider 通过公开 HTTPS URL 下载此文件。工作空间素材是私有的，Provider 无法访问；请改用指向同一文件的公开 HTTPS 链接。",
  "Sending…": "正在发送…",
  "Send queued change": "发送排队的更改",
  "This change is saved but has not been sent yet. Send it, or check its status before editing.": "此更改已保存但尚未发送。请发送，或在编辑前检查其状态。",
  "We could not confirm whether the Provider applied this change. Check its status before trying again.": "无法确认 Provider 是否已应用此更改。重试前请检查其状态。",
  "The change is saved but has not been sent. Send it, or check again before editing.": "更改已保存但尚未发送。请发送，或在再次检查前不要编辑。",
  "The Provider still has not confirmed this change. Do not repeat it.": "Provider 仍未确认此更改。请勿重复执行。",
  "Workspace media could not be loaded.": "无法加载工作空间素材。",
  "Workspace media must be 8 MiB or smaller.": "工作空间素材不得大于 8 MiB。",
