  "This replaces the saved catalog metadata for this route. Existing purchase rates and customer prices are preserved.": "这会替换此路由已保存目录元数据，保留现有采购费率与客户价格。",
  "Enabled for inference": "启用推理",
  "Disabled mappings remain in the directory.": "禁用的映射仍保留在目录中。",
  "Private model. Available only to the account that owns this API key.": "私有模型，仅限拥有此 API 密钥的账户使用。",
  "Show in public catalog": "在公开目录中显示",
  "Publish this alias in the unauthenticated model list.": "在无需身份验证的模型列表中发布此别名。",
  "Video configuration": "视频配置",
