  "Callback contract qualified for this schema": "此结构的回调合同已通过审核",
  "This declaration does not enable callbacks by itself. The adapter and offer review must support the same contract.": "此声明本身不会启用回调，适配器和报价审核必须支持同一合同。",
  "Remove configuration": "移除配置",
  "Apply configuration": "应用配置",
  "Prompt and text content": "提示词与文本内容",
  "Inline or HTTPS image references": "内联或 HTTPS 图像引用",
  "Video reference assets": "视频参考素材",
  "Audio reference assets": "音频参考素材",
  "Start from a template": "从模板开始",
  "Templates prefill channel, request limits, MIME types and pixel mappings. They are starting points, not verified model capabilities. Review every value against the Provider contract.": "模板会预填渠道、请求限制、MIME 类型和像素映射。它们只是起点，不代表已验证的模型能力。请根据 Provider 合同逐项核对。",
  "Template": "模板",
  "Choose a template": "选择模板",
  "Use template": "使用模板",
  "Using a template replaces this dialog’s draft. Review the advanced overrides before applying; nothing is saved until you apply the configuration and save the model mapping.": "使用模板会替换此对话框中的草稿。应用前请核对高级覆盖项；只有应用配置并保存模型映射后才会真正保存。",
  "Request limits": "请求限制",
  "Enter contracted limits for this exact model and channel. A template is a starting point, not a verified limit.": "输入此模型与渠道的合同限制。模板只是起点，不代表已验证的限制。",
  "Saving these limits does not qualify a live route; they apply only to this model and channel.": "保存这些限制不代表实时路由已通过资质审核；它们仅适用于此模型与渠道。",
  "Supported inputs": "支持的输入",
  "Choose the input kinds in the exact model and channel contract. Declaring a media input does not enable dispatch until transport, inspection and the exact contract are qualified.": "选择此模型与渠道合同允许的输入类型。媒体输入在传输、检查与精确合同通过审核前不会启用调度。",
  "Resolutions and aspect ratios": "分辨率与宽高比",
  "Select the output values this exact model and channel accepts. Pixel mappings are derived for standard dimensions and remain editable in advanced overrides.": "选择此模型与渠道接受的输出值。像素映射按标准尺寸生成，仍可在高级覆盖项中编辑。",
  "Resolutions": "分辨率",
