  "Rules inspect supported text before sending it upstream. Requests with unsupported tools, images or opaque content are blocked.": "规则在向上游发送前检查受支持文本。不支持的工具、图片或不透明内容会导致请求被拦截。",
  "Observe-only checks record matches without changing the response. Mandatory enforcement still applies. Streaming, tools, structured output and Embeddings are unsupported.": "仅观测检查记录匹配，不修改响应。强制规则仍适用。不支持流式响应、工具、结构化输出与向量嵌入。",
  "Buffered full-text inspection holds the response until checks finish. Streaming, tools, structured output and Embeddings are blocked when output rules are active.": "缓冲全文检查会保留响应直至检查完成。输出规则生效时会阻止流式响应、工具、结构化输出与向量嵌入。",
