  "Uses your own Provider API key. Your Provider bills this usage directly; it does not spend Niu credits. Access still depends on your key and Provider account.": "使用自有 Provider API 密钥，用量由 Provider 直接计费，不消耗 Niu 额度。访问仍取决于密钥与 Provider 账户。",
  "Uses Niu credits. Video cost depends on the request settings. Open Video to estimate the cost before submitting; a valid estimate is required to generate.": "使用 Niu 额度。视频费用取决于请求设置，请在提交前打开视频估算费用；生成需要有效估算。",
  "Uses Niu credits. Published prices do not guarantee model access or available supply; these are checked when you submit a request.": "使用 Niu 额度。已发布价格不保证模型访问权限或供给可用，提交请求时会检查。",
  "Billing information is unavailable. Refresh the catalog or ask your administrator to confirm how usage is billed before sending a request.": "计费信息不可用。发送请求前请刷新目录，或请管理员确认用量如何计费。",
